from pathlib import Path
import sys,json,hashlib
root=Path.cwd();out=root/'outputs/hive-prototype';work=root/'work/replication-coverage'
sys.path.insert(0,str(out));import knowledge
config=json.loads((root/'work/replication/client.json').read_text());db=Path(config['database'])
prior={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in out.glob('*.json')}
with (work/'prior-hashes.json').open('x') as f:json.dump(prior,f,indent=2)
record={'model':'gemma4:e4b','seed':11,'temperature':0.2,'database':str(db),'ingestion':knowledge.ingest(db,out/'README.md'),'queries':[]}
def save():(work/'population.json').write_text(json.dumps(record,indent=2)+'\n')
save()
for question,status in [('What happens when the model calculation disagrees?','supported_answer'),('What is the minimum Python version required?','supported_answer'),('Who manufactured the reservoir?','not_found_in_source')]:
 result=knowledge.answer_question(db,question,'gemma4:e4b',11,0.2)
 record['queries'].append({'question':question,'expected_status':status,'result':result});save()
 print(question,result,flush=True)
 if result['status']!=status:raise SystemExit('Unexpected result retained; do not proceed to recovery')
